PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admins(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','editor','reviewer','publisher','operator','viewer')), enabled INTEGER NOT NULL DEFAULT 1, preview_only INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, admin_id TEXT NOT NULL REFERENCES admins(id), csrf TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS objects(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('asset','character','content','event')), name TEXT NOT NULL, head INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS revisions(id TEXT PRIMARY KEY, object_id TEXT NOT NULL REFERENCES objects(id), number INTEGER NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','in_review','approved','rejected')), created_by TEXT NOT NULL REFERENCES admins(id), created_at TEXT NOT NULL, reviewed_by TEXT REFERENCES admins(id), review_note TEXT, reviewed_at TEXT, UNIQUE(object_id,number));
CREATE TABLE IF NOT EXISTS revision_refs(revision_id TEXT NOT NULL REFERENCES revisions(id), target_revision_id TEXT NOT NULL REFERENCES revisions(id), PRIMARY KEY(revision_id,target_revision_id));
CREATE TABLE IF NOT EXISTS blobs(digest TEXT PRIMARY KEY, media_type TEXT NOT NULL, size INTEGER NOT NULL, filename TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS releases(id TEXT PRIMARY KEY, name TEXT NOT NULL, manifest TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES admins(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS channels(name TEXT PRIMARY KEY CHECK(name IN ('preview','staging')), release_id TEXT REFERENCES releases(id));
CREATE TABLE IF NOT EXISTS channel_history(id INTEGER PRIMARY KEY AUTOINCREMENT, channel TEXT NOT NULL REFERENCES channels(name), release_id TEXT REFERENCES releases(id), previous_release_id TEXT, action TEXT NOT NULL, actor TEXT NOT NULL REFERENCES admins(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS executions(id TEXT PRIMARY KEY, release_id TEXT NOT NULL REFERENCES releases(id), revision_id TEXT NOT NULL REFERENCES revisions(id), actor TEXT NOT NULL REFERENCES admins(id), status TEXT NOT NULL CHECK(status IN ('preview_completed','cancelled','expired')), result TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT, request_id TEXT NOT NULL, actor TEXT, action TEXT NOT NULL, target TEXT, outcome TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency(actor TEXT NOT NULL, key TEXT NOT NULL, fingerprint TEXT NOT NULL, response TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(actor,key));
CREATE TRIGGER IF NOT EXISTS immutable_revision_payload BEFORE UPDATE OF object_id,number,payload,created_by,created_at ON revisions BEGIN SELECT RAISE(ABORT,'immutable revision'); END;
CREATE TRIGGER IF NOT EXISTS immutable_revision_delete BEFORE DELETE ON revisions BEGIN SELECT RAISE(ABORT,'immutable revision'); END;
CREATE TRIGGER IF NOT EXISTS immutable_ref_update BEFORE UPDATE ON revision_refs BEGIN SELECT RAISE(ABORT,'immutable reference'); END;
CREATE TRIGGER IF NOT EXISTS immutable_ref_delete BEFORE DELETE ON revision_refs BEGIN SELECT RAISE(ABORT,'immutable reference'); END;
CREATE TRIGGER IF NOT EXISTS immutable_release_update BEFORE UPDATE ON releases BEGIN SELECT RAISE(ABORT,'immutable release'); END;
CREATE TRIGGER IF NOT EXISTS immutable_release_delete BEFORE DELETE ON releases BEGIN SELECT RAISE(ABORT,'immutable release'); END;
CREATE TRIGGER IF NOT EXISTS immutable_audit_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'append only audit'); END;
CREATE TRIGGER IF NOT EXISTS immutable_audit_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'append only audit'); END;
CREATE TRIGGER IF NOT EXISTS immutable_history_update BEFORE UPDATE ON channel_history BEGIN SELECT RAISE(ABORT,'append only history'); END;
CREATE TRIGGER IF NOT EXISTS immutable_history_delete BEFORE DELETE ON channel_history BEGIN SELECT RAISE(ABORT,'append only history'); END;
